static List<String> resolveAll(String host) {
    try {
        InetAddress[] all = InetAddress.getAllByName(host);
        List<String> wynik = new ArrayList<>();
        for (InetAddress a : all) wynik.add(a.getHostAddress());
        return wynik;
    } catch (UnknownHostException e) { return List.of(); }
}
List<String> adresy = resolveAll("example.com");
System.out.println("liczba: "+adresy.size());

