static Map<String,String> resolveMultiple(String... hosts) {
    Map<String,String> wynik = new LinkedHashMap<>();
    for (String h : hosts) { try { wynik.put(h, InetAddress.getByName(h).getHostAddress()); } catch (UnknownHostException e) { wynik.put(h, "UNKNOWN"); } }
    return wynik;
}
System.out.println(resolveMultiple("localhost", "example.com", "nieistniejaca-xyz.test"));

