static Map<String,Boolean> checkHostsHealth(List<String> hosts, int timeoutMs) {
    Map<String,Boolean> wyniki = new LinkedHashMap<>();
    for (String h : hosts) {
        try { wyniki.put(h, InetAddress.getByName(h).isReachable(timeoutMs)); }
        catch (IOException e) { wyniki.put(h, false); }
    }
    return wyniki;
}
System.out.println(checkHostsHealth(List.of("localhost", "example.com", "nieistniejaca-xyz.test"), 1000));

static Set<String> commonAddresses(String host1, String host2) {
    try {
        Set<String> adresy1 = new HashSet<>();
        for (InetAddress a : InetAddress.getAllByName(host1)) adresy1.add(a.getHostAddress());
        Set<String> adresy2 = new HashSet<>();
        for (InetAddress a : InetAddress.getAllByName(host2)) adresy2.add(a.getHostAddress());
        adresy1.retainAll(adresy2);
        return adresy1;
    } catch (UnknownHostException e) { return Set.of(); }
}
System.out.println(commonAddresses("localhost", "localhost"));

static List<Boolean> monitorReachability(String host, int checks, int intervalMs, int timeoutMs) throws InterruptedException {
    List<Boolean> wyniki = new ArrayList<>();
    for (int i=0;i<checks;i++) {
        try { wyniki.add(InetAddress.getByName(host).isReachable(timeoutMs)); } catch (IOException e) { wyniki.add(false); }
        Thread.sleep(intervalMs);
    }
    return wyniki;
}
System.out.println(monitorReachability("example.com", 3, 200, 1000));

class SimpleDnsCache {
    private final Map<String,String> cache = new HashMap<>();
    String resolveWithCache(String host) throws UnknownHostException {
        if (cache.containsKey(host)) return cache.get(host);
        String adres = InetAddress.getByName(host).getHostAddress();
        cache.put(host, adres);
        return adres;
    }
}
SimpleDnsCache cache = new SimpleDnsCache();
long t0 = System.nanoTime();
cache.resolveWithCache("example.com");
long pierwsze = (System.nanoTime()-t0)/1_000_000;
t0 = System.nanoTime();
cache.resolveWithCache("example.com");
long drugie = (System.nanoTime()-t0)/1_000_000;
System.out.println("pierwsze: "+pierwsze+"ms drugie (z cache): "+drugie+"ms");

