static boolean allMethodsHandleFailureGracefully() {
    String zlaNazwa = "celowo-zla-domena-xyz999.test";
    boolean wszystkoOk = true;
    try { InetAddress.getByName(zlaNazwa); wszystkoOk = false; } catch (UnknownHostException e) { /* oczekiwane */ }
    try { InetAddress.getAllByName(zlaNazwa); wszystkoOk = false; } catch (UnknownHostException e) { /* oczekiwane */ }
    return wszystkoOk;
}
System.out.println(allMethodsHandleFailureGracefully());

static String classifyInetAddress(InetAddress addr) {
    if (addr.isLoopbackAddress()) return "LOOPBACK";
    if (addr.isSiteLocalAddress()) return "SITE_LOCAL";
    if (addr.isMulticastAddress()) return "MULTICAST";
    return "PUBLIC";
}
System.out.println(classifyInetAddress(InetAddress.getLoopbackAddress()));
try { System.out.println(classifyInetAddress(InetAddress.getByName("example.com"))); } catch (UnknownHostException e) {}

static String describeAddressBytes(InetAddress addr) {
    byte[] bajty = addr.getAddress();
    StringBuilder sb = new StringBuilder();
    for (byte b : bajty) sb.append(b & 0xFF).append(" ");
    return sb.toString().trim();
}
System.out.println(describeAddressBytes(InetAddress.getLoopbackAddress())); // 127 0 0 1

